<?php
require_once __DIR__ . '/../Config/koneksi.php';require_once __DIR__ . '/../Config/auth.php';madin_role_required('admin');require_once __DIR__.'/_layout.php';$id=(int)($_GET['id']??0);$stmt=mysqli_prepare($conn,'SELECT * FROM pesanan WHERE id_pesanan=? LIMIT 1');mysqli_stmt_bind_param($stmt,'i',$id);mysqli_stmt_execute($stmt);$order=mysqli_fetch_assoc(mysqli_stmt_get_result($stmt));mysqli_stmt_close($stmt);if(!$order){http_response_code(404);madin_admin_header('Detail Pesanan','pesanan');echo '<div class="admin-card">Pesanan tidak ditemukan. <a href="pesanan.php">Kembali</a></div>';madin_admin_footer();exit;}$stmt=mysqli_prepare($conn,'SELECT nama_produk,harga_satuan,jumlah,subtotal FROM detail_pesanan WHERE id_pesanan=?');mysqli_stmt_bind_param($stmt,'i',$id);mysqli_stmt_execute($stmt);$items=mysqli_stmt_get_result($stmt);madin_admin_header('Detail Pesanan','pesanan');?><div class="admin-card"><div class="table-actions" style="justify-content:space-between"><h2><?=madin_e($order['kode_pesanan'])?></h2><a class="btn secondary" href="pesanan.php">Kembali ke daftar</a></div><div class="admin-grid"><div class="stat-card"><div class="stat-label">Pelanggan</div><div class="stat-value" style="font-size:18px"><?=madin_e($order['nama_pelanggan'])?></div><p><?=madin_e($order['telepon_pelanggan']??'—')?></p></div><div class="stat-card"><div class="stat-label">Total</div><div class="stat-value"><?=madin_money($order['total'])?></div></div><div class="stat-card"><div class="stat-label">Pengambilan</div><div class="stat-value" style="font-size:18px"><?=madin_e(madin_status_label($order['jenis_pengambilan']))?></div></div></div><p><strong>Alamat:</strong> <?=nl2br(madin_e($order['alamat_pengantaran']??'Ambil sendiri'))?></p><p style="margin:12px 0"><strong>Catatan:</strong> <?=nl2br(madin_e($order['catatan']??'—'))?></p><p style="margin-bottom:12px"><strong>Status pesanan:</strong> <?=madin_e(madin_status_label($order['status_pesanan']))?> · <strong>Pembayaran:</strong> <?=madin_e(madin_status_label($order['status_pembayaran']))?></p><p><strong>Dibuat:</strong> <?=madin_e(date('d/m/Y H:i',strtotime($order['dibuat_pada'])))?></p></div><div class="admin-card"><h2>Rincian produk</h2><table class="admin-table"><thead><tr><th>Produk</th><th>Harga satuan</th><th>Jumlah</th><th>Subtotal</th></tr></thead><tbody><?php if($items&&mysqli_num_rows($items)):while($item=mysqli_fetch_assoc($items)):?><tr><td><?=madin_e($item['nama_produk'])?></td><td><?=madin_money($item['harga_satuan'])?></td><td><?=$item['jumlah']?></td><td><?=madin_money($item['subtotal'])?></td></tr><?php endwhile;else:?><tr><td colspan="4" class="empty-state">Tidak ada rincian item tersimpan.</td></tr><?php endif;?></tbody></table></div><?php mysqli_stmt_close($stmt);madin_admin_footer();?>
